    rows.append([lab]+[P(br,p,'quota_surplus') for p in PER]+[P(br,p,'inv_su_surplus') for p in PER]+[(P(br,p,'crescita_VA_reale') if not pd.isna(t[(t.branca==br)&(t.periodo==p)]['crescita_VA_reale'].iloc[0]) else '—') for p in PER])
